namespace CleanArchitecture.Blazor.Application.Features.Subsystems.EventHandlers;

public class SubsystemDeletedEventHandler : INotificationHandler<SubsystemDeletedEvent>
{
    private readonly ILogger<SubsystemDeletedEventHandler> _logger;

    public SubsystemDeletedEventHandler(
        ILogger<SubsystemDeletedEventHandler> logger
    )
    {
        _logger = logger;
    }

    public Task Handle(SubsystemDeletedEvent notification, CancellationToken cancellationToken)
    {
        _logger.LogInformation("Subsystem deleted: {SubsystemName} (ID: {SubsystemId}) under System ID: {SystemId} by {DeletedBy} at {DeletedOn}", 
            notification.Item.Name, 
            notification.Item.Id,
            notification.Item.SystemId,
            notification.Item.LastModifiedBy, 
            notification.Item.LastModified);
        
        return Task.CompletedTask;
    }
}